## Code Example
```javascript
import { test, expect } from '@playwright/test';

test('onboarding with feature flag', async ({ page, request }) => {
  // Seed user with onboarding flag ON
  await request.post('/api/test/setup-user', { data: { flagName: 'new-onboarding', value: true } });
  // Login and navigate
  await page.goto('/login');
  await page.fill('#email', 'user@example.com');
  await page.fill('#password', 's3cret');
  await page.click('button[type="submit"]');
  await page.waitForURL('/dashboard');

  // Verify onboarding visible
  await expect(page.locator('#onboarding-panel')).toBeVisible();
  await expect(page.locator('#onboarding-panel .step')).toHaveCount(4);

  // Complete first step
  await page.click('#step-1 .complete');
  await expect(page.locator('#step-1')).toHaveClass(/completed/);

  // Refresh and verify persistence
  await page.reload();
  await expect(page.locator('#step-1')).toHaveClass(/completed/);

  // Turn flag OFF mid-flow and verify UI hides, but backend progress remains
  await request.post('/api/test/setup-user', { data: { flagName: 'new-onboarding', value: false } });
  await page.reload();
  await expect(page.locator('#onboarding-panel')).toBeHidden();

  // Validate backend progress still retrievable
  const res = await request.get('/api/user/progress');
  expect(res.status()).toBe(200);
  const data = await res.json();
  expect(data.stepsCompleted).toBe(1);
});
```

